173	fn finally_contains_comments(
174	    preceding_stmt: Option<&Stmt>,
175	    preceding_end: TextSize,
176	    finalbody_stmt: &Stmt,
177	    finally_range: TextRange,
178	    checker: &Checker,
179	) -> bool {
180	    let source = checker.source();
181	    let finally_full_end = source.full_line_end(finally_range.end());
182	    let commentable_range = TextRange::new(finally_range.start(), finally_full_end);
183	
184	    // A comment after the `finally` keyword or after the dummy statement
185	    if checker.comment_ranges().intersects(commentable_range) {
186	        return true;
187	    }
188	
189	    let Some(preceding_stmt) = preceding_stmt else {
190	        return false;
191	    };
192	
193	    finally_has_preceding_comment(preceding_stmt, preceding_end, finally_range, checker)
194	        || finally_has_trailing_comment(finalbody_stmt, finally_full_end, checker)
195	}
