203	    // Look at the indentation of the first non-empty line, to determine the "baseline" indentation.
204	    //
205	    // A leading formfeed (`\x0C`) is not part of a line's whitespace indentation: Python resets the
206	    // column count when it sees one. Strip any leading formfeeds before measuring the indentation so
207	    // that the baseline reflects the actual whitespace indentation.
208	    let mut first_comment = None;
209	    let existing_indent_len = text
210	        .universal_newlines()
211	        .find_map(|line| {
212	            let without_formfeed = line.trim_start_matches('\x0C');
213	            let trimmed = without_formfeed.trim_whitespace_start();
214	            if trimmed.is_empty() {
215	                None
216	            } else if trimmed.starts_with('#') && first_comment.is_none() {
217	                first_comment = Some(without_formfeed.len() - trimmed.len());
218	                None
219	            } else {
220	                Some(without_formfeed.len() - trimmed.len())
221	            }
222	        })
223	        .unwrap_or(first_comment.unwrap_or_default());
224	
225	    if existing_indent_len < indent.len() {
226	        return None;
227	    }
228	
229	    // Determine the amount of indentation to remove.
230	    let dedent_len = existing_indent_len - indent.len();
231	
232	    let mut result = String::with_capacity(text.len() + indent.len());
233	    for line in text.universal_newlines() {
234	        let trimmed = line.trim_whitespace_start();
235	        if trimmed.is_empty() {
236	            if let Some(line_ending) = line.line_ending() {
237	                result.push_str(&line_ending);
238	            }
239	        } else {
240	            let full = line.as_full_str();
241	            // Preserve any leading formfeed characters; they are not part of the indentation and
242	            // must be re-prepended after the indentation is removed.
243	            let formfeed_len = full.len() - full.trim_start_matches('\x0C').len();
244	            let after_formfeed = &full[formfeed_len..];
245	
246	            // Determine the current indentation level (after the leading formfeeds).
247	            let current_indent_len =
248	                after_formfeed.len() - after_formfeed.trim_whitespace_start().len();
249	            if current_indent_len < existing_indent_len {
250	                // If the current indentation level is less than the baseline, keep it as is.
251	                result.push_str(full);
252	            } else {
253	                // Otherwise, reduce the indentation level, keeping the leading formfeeds intact.
254	                result.push_str(&full[..formfeed_len]);
255	                result.push_str(&after_formfeed[dedent_len..]);
256	            }
257	        }
258	    }
259	    Some(result)
260	}
